DROP TABLE IF EXISTS `POD`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `POD` (
  `id` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `jobFileId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `deliveryAssigned` tinyint(1) NOT NULL DEFAULT '1',
  `deliveryStatus` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Pending',
  `deliveryAssignedAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `deliveryAssignedById` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `driverName` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `driverMobile` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `driverUid` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `isExternal` tinyint(1) NOT NULL DEFAULT '0',
  `deliveryLocation` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `deliveryNotes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `completedAt` datetime(3) DEFAULT NULL,
  `receiverName` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `receiverMobile` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `receivedByName` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `receivedByRelation` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `signatureDataUrl` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `photoDataUrl` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `latitude` double DEFAULT NULL,
  `longitude` double DEFAULT NULL,
  `geolocationName` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `deliveredDate` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `feedbackStatus` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `feedbackRating` int DEFAULT NULL,
  `feedbackComments` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `publicPodToken` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `POD_publicPodToken_key` (`publicPodToken`),
  KEY `POD_jobFileId_idx` (`jobFileId`),
  KEY `POD_deliveryStatus_idx` (`deliveryStatus`),
  KEY `POD_driverUid_idx` (`driverUid`),
  KEY `POD_publicPodToken_idx` (`publicPodToken`),
  KEY `POD_deliveryAssignedById_fkey` (`deliveryAssignedById`),
  CONSTRAINT `POD_deliveryAssignedById_fkey` FOREIGN KEY (`deliveryAssignedById`) REFERENCES `User` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `POD_jobFileId_fkey` FOREIGN KEY (`jobFileId`) REFERENCES `JobFile` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
