--
-- Table structure for table `material_issues`
--

DROP TABLE IF EXISTS `material_issues`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `material_issues` (
  `id` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `jobId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `issueType` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'JOB',
  `reference` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `materialId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `stockBatchId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `quantity` int NOT NULL,
  `unitCost` double NOT NULL,
  `totalCost` double NOT NULL,
  `rackId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `issuedById` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `issuedAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `notes` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `companyId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`),
  KEY `material_issues_jobId_fkey` (`jobId`),
  KEY `material_issues_materialId_fkey` (`materialId`),
  KEY `material_issues_stockBatchId_fkey` (`stockBatchId`),
  KEY `material_issues_rackId_fkey` (`rackId`),
  KEY `material_issues_issuedById_fkey` (`issuedById`),
  KEY `material_issues_companyId_fkey` (`companyId`),
  CONSTRAINT `material_issues_companyId_fkey` FOREIGN KEY (`companyId`) REFERENCES `companies` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `material_issues_issuedById_fkey` FOREIGN KEY (`issuedById`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `material_issues_jobId_fkey` FOREIGN KEY (`jobId`) REFERENCES `moving_jobs` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `material_issues_materialId_fkey` FOREIGN KEY (`materialId`) REFERENCES `packing_materials` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `material_issues_rackId_fkey` FOREIGN KEY (`rackId`) REFERENCES `racks` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `material_issues_stockBatchId_fkey` FOREIGN KEY (`stockBatchId`) REFERENCES `stock_batches` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

