DROP TABLE IF EXISTS `shipment_charges`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `shipment_charges` (
  `id` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `shipmentId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `companyId` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `currentStorageCharge` double NOT NULL DEFAULT '0',
  `daysStored` int NOT NULL DEFAULT '0',
  `lastCalculatedDate` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `totalBoxesReleased` int NOT NULL DEFAULT '0',
  `totalInvoiced` double NOT NULL DEFAULT '0',
  `totalPaid` double NOT NULL DEFAULT '0',
  `outstandingBalance` double NOT NULL DEFAULT '0',
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `shipment_charges_shipmentId_key` (`shipmentId`),
  KEY `shipment_charges_companyId_fkey` (`companyId`),
  CONSTRAINT `shipment_charges_companyId_fkey` FOREIGN KEY (`companyId`) REFERENCES `companies` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `shipment_charges_shipmentId_fkey` FOREIGN KEY (`shipmentId`) REFERENCES `shipments` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
